import { BUSINESS_CONTEXT, complete, readBody, send, aiMode, clip } from "./_lib/llm.js";

// POST /api/brief  { business, industry, goal, audience }
// Returns a structured website plan (JSON) generated by the LLM.
export default async function handler(req, res) {
  if (req.method !== "POST") return send(res, 405, { error: "Use POST" });
  const b = await readBody(req);
  const input = {
    business: clip(b.business, 120) || "My Business",
    industry: clip(b.industry, 80) || "General",
    goal: clip(b.goal, 200) || "Get more customers",
    audience: clip(b.audience, 200) || "Local customers",
  };

  const system = `${BUSINESS_CONTEXT}
You are now acting as Nicom's website strategist. Return ONLY valid JSON with this shape:
{"headline": string, "subheadline": string, "pages": [{"name": string, "purpose": string}],
 "aiFeatures": [{"name": string, "benefit": string}], "seoKeywords": [string], "cta": string}
Use 4-6 pages, exactly 3 aiFeatures, 6 seoKeywords. Make it specific to the business and South African market.`;

  try {
    const raw = await complete({
      system,
      json: true,
      temperature: 0.7,
      messages: [{ role: "user", content: JSON.stringify(input) }],
    });
    if (raw !== null) return send(res, 200, { brief: JSON.parse(raw), mode: "live" });
  } catch (err) {
    console.error(err);
  }
  return send(res, 200, { brief: demoBrief(input), mode: aiMode() === "live" ? "fallback" : "demo" });
}

function demoBrief({ business, industry, goal, audience }) {
  const ind = industry.toLowerCase();
  const loc = /cape town|joburg|johannesburg|durban|pretoria/i.test(audience) ? audience : "South Africa";
  return {
    headline: `${business}: ${industry} done properly, online and on time`,
    subheadline: `Built to help ${audience.toLowerCase()} find you, trust you and ${goal.toLowerCase()}.`,
    pages: [
      { name: "Home", purpose: "Clear promise, proof (reviews), and one primary call to action." },
      { name: "Services", purpose: `Each ${ind} service with outcomes, FAQs and a quote button.` },
      { name: "Work / Results", purpose: "Case studies and before/after examples that build trust." },
      { name: "About", purpose: "Your story, team and why locals choose you." },
      { name: "Contact", purpose: "AI-qualified enquiry form, WhatsApp button, map and hours." },
    ],
    aiFeatures: [
      { name: "24/7 AI chat agent", benefit: `Answers ${ind} questions instantly and captures leads after hours.` },
      { name: "Smart lead qualifier", benefit: "Scores every enquiry and routes hot leads to you by WhatsApp." },
      { name: "AI content engine", benefit: "Drafts blog posts and social captions from your service list each week." },
    ],
    seoKeywords: [
      `${ind} ${loc}`.toLowerCase(),
      `best ${ind} near me`,
      `${ind} services`,
      `affordable ${ind}`,
      `${business.toLowerCase()} reviews`,
      `${ind} quote`,
    ],
    cta: "Book a free consultation",
  };
}
